// Runtime probe for IDEA-1054: drive the real HTTP server via the test harness.
import { pathToFileURL } from "node:url";
import path from "node:path";

const repo = process.argv[2];
const { makeHarness } = await import(pathToFileURL(path.join(repo, "tests/helpers.js")).href);

const cleanups = [];
const t = { after: (fn) => cleanups.push(fn) };
const EVIL = "https://evil.example";

async function call(h, method, p, { origin = EVIL, body, type = "application/json", key } = {}) {
  const headers = {};
  if (origin) headers.Origin = origin;
  if (body !== undefined) headers["Content-Type"] = type;
  if (key) headers.Authorization = `Bearer ${key}`;
  const res = await fetch(h.base + p, { method, headers, body: body === undefined ? undefined : JSON.stringify(body) });
  const text = await res.text();
  return `${res.status} acao=${res.headers.get("access-control-allow-origin") ?? "-"} ${text.slice(0, 90).replace(/\s+/g, " ")}`;
}

