// Runtime probe for IDEA-967: how does the scan-time GGUF reader handle hostile headers?
// Each case runs in its own child with a heap cap and a wall-clock timeout.
import { spawnSync } from "node:child_process";
import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { pathToFileURL } from "node:url";

const repo = process.argv[2];
const mode = process.argv[3];

function header({ tensors, kvs, keyLen = 4n }) {
  const b = Buffer.alloc(4 + 4 + 8 + 8 + 8 + 4);
  b.write("GGUF", 0, "latin1");
  b.writeUInt32LE(3, 4);
  b.writeBigUInt64LE(tensors, 8);
  b.writeBigUInt64LE(kvs, 16);
  b.writeBigUInt64LE(keyLen, 24); // first KV key length
  b.write("abcd", 32, "latin1");
  return Buffer.concat([b, Buffer.alloc(64)]);
}

if (mode === "child") {
  const [file] = process.argv.slice(4);
  const { readGgufFileInfo } = await import(pathToFileURL(path.join(repo, "node_modules/node-llama-cpp/dist/index.js")).href);
  const started = Date.now();
  try {
    await readGgufFileInfo(file, { readTensorInfo: true, logWarnings: false, spliceSplitFiles: false });
    console.log(`parsed OK in ${Date.now() - started}ms`);
  } catch (error) {
    console.log(`threw in ${Date.now() - started}ms: ${String(error.message).slice(0, 100)}`);
  }
} else {
  const dir = mkdtempSync(path.join(os.tmpdir(), "probe-967-"));
  const cases = {
    "huge tensor count (2^62), tiny file": header({ tensors: 1n << 62n, kvs: 0n }),
    "huge KV count (2^62), tiny file": header({ tensors: 0n, kvs: 1n << 62n }),
    "first key length 2^40 in a 100-byte file": header({ tensors: 0n, kvs: 1n, keyLen: 1n << 40n }),
  };
  for (const [name, buf] of Object.entries(cases)) {
    const file = path.join(dir, "m.gguf");
    writeFileSync(file, buf);
    const r = spawnSync(process.execPath, ["--max-old-space-size=256", process.argv[1], repo, "child", file], { timeout: 20000, encoding: "utf8" });
    const out = (r.stdout || "").trim() || (r.stderr || "").split("\n").find((l) => /heap|memory|Error/i.test(l)) || "";
    console.log(`${name}: ${r.error?.code === "ETIMEDOUT" ? "TIMEOUT 20s" : `exit ${r.status}`} ${out.slice(0, 140)}`);
  }
  rmSync(dir, { recursive: true, force: true });
}

