import { pathToFileURL } from "node:url";
import path from "node:path";
import os from "node:os";
import { mkdtemp, readdir, readFile, rm } from "node:fs/promises";

const repo = process.argv[2];
const { DownloadManager } = await import(pathToFileURL(path.join(repo, "src/downloader.js")).href);
const { MODEL_CATALOG } = await import(pathToFileURL(path.join(repo, "src/model-catalog.js")).href).catch(() => ({}));

const dir = await mkdtemp(path.join(os.tmpdir(), "probe-862-"));
try {
  const id = "smollm2-135m-instruct-q4";
  const entry = (MODEL_CATALOG || []).find?.((m) => m.id === id);
  const size = entry?.size ?? 105454432;
  console.log("catalog entry has hash field:", entry ? Object.keys(entry).filter((k) => /sha|hash|digest/i.test(k)).join(",") || "none" : "catalog export not found");
  let seenUrl = "";
  const fetchImpl = async (url) => {
    seenUrl = String(url);
    const chunk = Buffer.alloc(1 << 20, 0x41); // "AAAA..." – not the real model
    let sent = 0;
    const body = new ReadableStream({
      pull(controller) {
        if (sent >= size) return controller.close();
        const n = Math.min(chunk.length, size - sent);
        controller.enqueue(new Uint8Array(chunk.subarray(0, n)));
        sent += n;
      },
    });
    return new Response(body, { status: 200, headers: { "content-length": String(size) } });
  };
  const manager = new DownloadManager({ modelsDir: dir, logger: { warn() {}, error() {}, info() {} }, fetchImpl });
