// Probe for IDEA-882: two downloads of the same catalog model at once.
import { pathToFileURL } from "node:url";
import path from "node:path";
import os from "node:os";
import { mkdtemp, readdir, stat, rm } from "node:fs/promises";

const repo = process.argv[2];
const { DownloadManager } = await import(pathToFileURL(path.join(repo, "src/downloader.js")).href);
const { MODEL_CATALOG } = await import(pathToFileURL(path.join(repo, "src/model-catalog.js")).href);

const id = "smollm2-135m-instruct-q4";
const size = MODEL_CATALOG.find((m) => m.id === id).size;
const dir = await mkdtemp(path.join(os.tmpdir(), "probe-882-"));
try {
  const fetchImpl = async () => {
    const chunk = Buffer.alloc(1 << 20, 0x47);
    let sent = 0;
    const body = new ReadableStream({
      async pull(controller) {
        if (sent >= size) return controller.close();
        await new Promise((r) => setImmediate(r));
        const n = Math.min(chunk.length, size - sent);
        controller.enqueue(new Uint8Array(chunk.subarray(0, n)));
        sent += n;
      },
    });
    return new Response(body, { status: 200, headers: { "content-length": String(size) } });
  };
  const manager = new DownloadManager({ modelsDir: dir, logger: { warn() {}, error() {}, info() {} }, fetchImpl });
  let second;
  const first = await manager.start(id);
  try { second = await manager.start(id); } catch (e) { console.log("second start refused:", e.code); }
  const ids = [first.id, second?.id].filter(Boolean);
  for (let i = 0; i < 400; i += 1) {
    if (ids.every((j) => !["queued", "downloading"].includes(manager.get(j)?.status))) break;
    await new Promise((r) => setTimeout(r, 25));
  }
  console.log("jobs:", ids.map((j) => manager.get(j)?.status).join(", "));
  for (const f of await readdir(dir)) console.log(" ", f, (await stat(path.join(dir, f))).size, f.endsWith(".gguf") ? `(catalog size ${size})` : "");
} finally {
  await rm(dir, { recursive: true, force: true });
}

